//--------------------------------------------------------------------------//
//! \desc  Increases the age counter in the RAM cache image, checking for
//!        overflow.
//!
//!        Under normal operating conditions, there should never be an overlow.

//! \assume There is a valid FLASH image already loaded into RAM cache.\n
//!         Has been called from within a 'NvramTry' block.

//! \notes  -none-

//  \param  -none-

//! \return \b void
//!

//! \throws \b Nvram_Status : \b NVRAM_ERR_INTERNAL If error detected.
//--------------------------------------------------------------------------//

void nvram_cache_age (void)
{
  Nvram_Header * const header_c = IMAGE_HEADER (nvram_image_cache) ;

  if (header_c->image_info.data_age < 0xFFFFFFFF)
    {
      header_c->image_info.data_age ++ ;
    }
  else
    {
      NvramThrow NVRAM_ERR_INTERNAL ;
    }
}

